prologue:
/* A colour packed as 0xAARRGGBB is what the game draws with, but pixels are kept as RGBA
   bytes, which is the order Create and Replace read them in */
static MOD_UNUSED int texture_channel(float value) {
    int out = (int)(value * 255.0f + 0.5f);
    if (out < 0) out = 0;
    if (out > 255) out = 255;
    return out;
}

/* Canvases the mod paints on. Two of them, big enough for a font sheet; a canvas costs its
   pixels and nothing else, and the mod pays for it once */
enum { kCanvases = 2, kCanvasSide = 256 };
static char g_canvas_named[kCanvases][32];
static unsigned char g_canvas_pixels[kCanvases][kCanvasSide * kCanvasSide * 4];
static int g_canvas_wide[kCanvases];
static int g_canvas_tall[kCanvases];

static MOD_UNUSED int canvas_slot(const char* name, int make) {
    int at, free_slot = -1;
    if (name == 0 || name[0] == 0) return -1;
    for (at = 0; at < kCanvases; ++at) {
        if (g_canvas_named[at][0] == 0) {
            if (free_slot < 0) free_slot = at;
            continue;
        }
        if (strcmp(g_canvas_named[at], name) == 0) return at;
    }
    if (make == 0 || free_slot < 0 || strlen(name) >= sizeof g_canvas_named[0]) return -1;
    strcpy(g_canvas_named[free_slot], name);
    return free_slot;
}

static MOD_UNUSED void canvas_new(const char* name, int wide, int tall) {
    const int slot = canvas_slot(name, 1);
    if (slot < 0) return;
    if (wide < 1) wide = 1;
    if (tall < 1) tall = 1;
    if (wide > kCanvasSide) wide = kCanvasSide;
    if (tall > kCanvasSide) tall = kCanvasSide;
    g_canvas_wide[slot] = wide;
    g_canvas_tall[slot] = tall;
    memset(g_canvas_pixels[slot], 0, (size_t)wide * (size_t)tall * 4);
}

static MOD_UNUSED int canvas_size(const char* name, int want_width) {
    const int slot = canvas_slot(name, 0);
    if (slot < 0) return 0;
    return want_width ? g_canvas_wide[slot] : g_canvas_tall[slot];
}

static MOD_UNUSED void canvas_set(const char* name, int x, int y, float r, float g, float b, float a) {
    const int slot = canvas_slot(name, 0);
    unsigned char* pixel;
    if (slot < 0 || x < 0 || y < 0 || x >= g_canvas_wide[slot] || y >= g_canvas_tall[slot]) return;
    pixel = g_canvas_pixels[slot] + ((size_t)y * (size_t)g_canvas_wide[slot] + (size_t)x) * 4;
    pixel[0] = (unsigned char)texture_channel(r);
    pixel[1] = (unsigned char)texture_channel(g);
    pixel[2] = (unsigned char)texture_channel(b);
    pixel[3] = (unsigned char)texture_channel(a);
}

/* 0 is red, 1 green, 2 blue, 3 alpha; a pixel outside the canvas reads as nothing */
static MOD_UNUSED float canvas_get(const char* name, int x, int y, int channel) {
    const int slot = canvas_slot(name, 0);
    if (slot < 0 || channel < 0 || channel > 3) return 0.0f;
    if (x < 0 || y < 0 || x >= g_canvas_wide[slot] || y >= g_canvas_tall[slot]) return 0.0f;
    return g_canvas_pixels[slot][((size_t)y * (size_t)g_canvas_wide[slot] + (size_t)x) * 4 + channel]
           / 255.0f;
}

static MOD_UNUSED void canvas_fill(const char* name, int x, int y, int wide, int tall,
                                   float r, float g, float b, float a) {
    int across, down;
    for (down = 0; down < tall; ++down)
        for (across = 0; across < wide; ++across)
            canvas_set(name, x + across, y + down, r, g, b, a);
}

/* Pictures the mod made, kept by name so a sheet never carries an id */
enum { kMadeTextures = 8 };
static char g_texture_named[kMadeTextures][64];
static AmodTextureId g_texture_id[kMadeTextures];

static MOD_UNUSED AmodTextureId texture_named(const char* name) {
    int at;
    for (at = 0; at < kMadeTextures; ++at)
        if (g_texture_named[at][0] != 0 && strcmp(g_texture_named[at], name) == 0)
            return g_texture_id[at];
    return AMOD_INVALID_TEXTURE;
}

static MOD_UNUSED void texture_remember(const char* name, AmodTextureId id) {
    int at;
    for (at = 0; at < kMadeTextures; ++at) {
        if (g_texture_named[at][0] != 0 && strcmp(g_texture_named[at], name) != 0) continue;
        if (strlen(name) >= sizeof g_texture_named[0]) return;
        strcpy(g_texture_named[at], name);
        g_texture_id[at] = id;
        return;
    }
}

/* The picture behind a name: one the mod made, otherwise the game's by path */
static MOD_UNUSED AmodTextureId texture_any(const char* name) {
    AmodTextureId id = texture_named(name);
    if (id != AMOD_INVALID_TEXTURE) return id;
    if (API->textures == 0) return AMOD_INVALID_TEXTURE;
    id = API->textures->Find(SELF, name);
    if (id == AMOD_INVALID_TEXTURE) id = API->textures->Load(SELF, name, 0, 1);
    return id;
}

/* Canvas to picture. The same name twice replaces the pixels instead of making another one,
   so a picture that changes every frame stays one picture */
static MOD_UNUSED void canvas_to_texture(const char* canvas, const char* name) {
    const int slot = canvas_slot(canvas, 0);
    const AmodTextureId had = texture_named(name);
    if (slot < 0 || API->textures == 0) return;

    if (had != AMOD_INVALID_TEXTURE &&
        API->textures->Replace(SELF, had, g_canvas_wide[slot], g_canvas_tall[slot],
                               g_canvas_pixels[slot]) != 0)
        return;

    {
        const AmodTextureId made = API->textures->Create(SELF, g_canvas_wide[slot],
                                                         g_canvas_tall[slot],
                                                         g_canvas_pixels[slot], 0, 1);
        if (made != AMOD_INVALID_TEXTURE) texture_remember(name, made);
    }
}

/* The other way round: what a picture holds, so a sheet can read it pixel by pixel */
static MOD_UNUSED void texture_to_canvas(const char* name, const char* canvas) {
    AmodTexture info;
    const AmodTextureId id = texture_any(name);
    int slot;
    if (id == AMOD_INVALID_TEXTURE || API->textures == 0) return;

    memset(&info, 0, sizeof info);
    info.structSize = sizeof info;
    if (API->textures->Get(SELF, id, &info) == 0) return;

    canvas_new(canvas, info.width, info.height);
    slot = canvas_slot(canvas, 0);
    if (slot < 0) return;
    API->textures->ReadPixels(SELF, id, g_canvas_pixels[slot],
                              g_canvas_wide[slot] * g_canvas_tall[slot] * 4);
}

static MOD_UNUSED int texture_size(const char* name, int want_width) {
    AmodTexture info;
    const AmodTextureId id = texture_any(name);
    if (id == AMOD_INVALID_TEXTURE || API->textures == 0) return 0;
    memset(&info, 0, sizeof info);
    info.structSize = sizeof info;
    if (API->textures->Get(SELF, id, &info) == 0) return 0;
    return want_width ? info.width : info.height;
}

static MOD_UNUSED const char* texture_name_at(int index) {
    AmodTexture info;
    AmodTextureId id;
    if (API->textures == 0) return "";
    id = API->textures->GetAt(SELF, index);
    memset(&info, 0, sizeof info);
    info.structSize = sizeof info;
    if (id == AMOD_INVALID_TEXTURE || API->textures->Get(SELF, id, &info) == 0) return "";
    return info.name != 0 ? info.name : "";
}

/* Everything that asks the game for this path gets the mod's picture instead, which is how a
   made-up picture reaches a subsystem that only takes paths */
static MOD_UNUSED void texture_override(const char* path, const char* name) {
    const AmodTextureId id = texture_any(name);
    if (id != AMOD_INVALID_TEXTURE && API->textures != 0)
        API->textures->Override(SELF, path, id);
}

static MOD_UNUSED void texture_release(const char* name) {
    const AmodTextureId id = texture_named(name);
    int at;
    if (id == AMOD_INVALID_TEXTURE || API->textures == 0) return;
    API->textures->Release(SELF, id);
    for (at = 0; at < kMadeTextures; ++at)
        if (strcmp(g_texture_named[at], name) == 0) g_texture_named[at][0] = 0;
}
